preset_css:
/* Antiquarian Inject */
.mor-post .post-body::first-letter { color: var(--accent); float: left; font-size: 4rem; line-height: 1; margin: 0 8px 0 0; padding: 4px; border: 1px solid var(--border-color); }
.mor-post { border-top: 4px double var(--border-color); border-bottom: 4px double var(--border-color); }
.main-header { border-bottom: 1px solid var(--accent); }
h1, h2 { text-transform: capitalize; font-variant: small-caps; }
